import {poolStart,poolMove,poolBot} from './pool.js?v=20261104-lobby2';
import {cardsStart,cardsMove,cardsLegal} from './cards.js?v=20261104-lobby2';
import {sketchStart} from './sketch.js?v=20261104-lobby2';
import {chessStart,chessMove,chessLegal,chessBot} from './chess-rules.js?v=20261104-lobby2';
export function start(game){if(game==='pool')return poolStart();if(game==='cards')return cardsStart();if(game==='draw')return sketchStart();if(game==='chess')return chessStart();const cells=game==='puzzle'?Array.from({length:16},(_,i)=>i+1):Array(game==='four'?42:225).fill(0);if(game==='puzzle')for(let i=15;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cells[i],cells[j]]=[cells[j],cells[i]];}return{game,cells,turn:1,winner:0,over:false,moves:0};}
export function move(s,actor,position){if(s.over||s.turn!==actor)throw Error('turn');if(s.game==='pool')return poolMove(s,actor,position);if(s.game==='cards')return cardsMove(s,actor,position);if(s.game==='puzzle'){if(!Number.isInteger(position)||position<0||position>=256)throw Error('tile');const a=Math.floor(position/16),b=position%16;if(a===b)throw Error('tile');const cells=s.cells.slice();[cells[a],cells[b]]=[cells[b],cells[a]];const solved=cells.every((n,i)=>n===i+1);return{...s,cells,turn:3-actor,winner:solved?1:0,over:solved,moves:s.moves+1};}if(s.game==='chess')return chessMove(s,actor,position);const width=s.game==='four'?7:15;let index=position;if(s.game==='four'){if(position<0||position>6)throw Error('column');index=-1;for(let r=5;r>=0;r--)if(!s.cells[r*7+position]){index=r*7+position;break;}}if(!Number.isInteger(index)||index<0||index>=s.cells.length||s.cells[index])throw Error('occupied');const cells=s.cells.slice();cells[index]=actor;let win=false;for(const [dx,dy] of [[1,0],[0,1],[1,1],[1,-1]]){let count=1;for(const sign of [-1,1]){let x=index%width+dx*sign,y=Math.floor(index/width)+dy*sign;while(x>=0&&x<width&&y>=0&&y<cells.length/width&&cells[y*width+x]===actor){count++;x+=dx*sign;y+=dy*sign;}}if(count>=(s.game==='four'?4:5))win=true;}return{...s,cells,turn:3-actor,winner:win?actor:0,over:win||s.moves+1===cells.length,moves:s.moves+1};}
export const legal=s=>s.over?[]:s.game==='cards'?cardsLegal(s):s.game==='chess'?chessLegal(s):s.game==='four'?[0,1,2,3,4,5,6].filter(c=>!s.cells[c]):s.cells.flatMap((v,i)=>v?[]:[i]);
export function bot(s){if(s.game==='pool')return poolBot(s);if(s.game==='cards')return cardsLegal(s)[0];if(s.game==='chess')return chessBot(s);if(s.game==='puzzle'){const a=s.cells.findIndex((n,i)=>n!==i+1);return a*16+s.cells.indexOf(a+1);}const moves=legal(s);for(const p of moves)if(move(s,s.turn,p).winner===s.turn)return p;const opponent={...s,turn:3-s.turn};for(const p of moves)if(move(opponent,opponent.turn,p).winner===opponent.turn)return p;return moves.sort((a,b)=>score(b)-score(a))[0];function score(p){if(s.game==='four')return-Math.abs(p-3);let score=-Math.abs(p%15-7)-Math.abs(Math.floor(p/15)-7);s.cells.forEach((v,i)=>{if(v&&Math.abs(i%15-p%15)<=2&&Math.abs(Math.floor(i/15)-Math.floor(p/15))<=2)score+=v===s.turn?5:4;});return score;}}
